/* @autogenerated */
package net.civeira.phylax.feature.oauth.client.infrastructure.driven;

import java.util.Optional;

import org.jose4j.jwe.JsonWebEncryption;
import org.jose4j.jwk.JsonWebKey;
import org.jose4j.jwk.JsonWebKeySet;
import org.jose4j.jwk.PublicJsonWebKey;
import org.jose4j.jwk.RsaJsonWebKey;
import org.jose4j.lang.JoseException;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;
import net.civeira.phylax.feature.oauth.client.domain.gateway.ClientJwtEncryptionGateway;

/**
 * JWE for a client with jose4j (task 4.5): the first RSA key of its JWKS (inline, or
 * {@code jwks_uri} through {@link RemoteJwksFetcher}) meant for encryption ({@code use=enc}, or
 * without {@code use}), RSA-OAEP or RSA-OAEP-256 and an AES content encryption. Anything else is
 * refused, so a response is never sent in clear to a client that asked for encryption.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class JweEncryptionAdapter implements ClientJwtEncryptionGateway {

  private final RemoteJwksFetcher fetcher;

  @Override
  public String encrypt(ClientDetails client, String payload, boolean nested, String alg,
      String enc) {
    String method = enc == null || enc.isBlank() ? DEFAULT_ENCRYPTION : enc;
    if (!ALGORITHMS.contains(alg) || !ENCRYPTIONS.contains(method)) {
      throw new IllegalStateException("Unsupported JWE algorithm " + alg + "/" + method);
    }
    PublicJsonWebKey key = encryptionKey(client).orElseThrow(() -> new IllegalStateException(
        "Client " + client.getClientId() + " has no RSA encryption key"));
    try {
      JsonWebEncryption jwe = new JsonWebEncryption();
      jwe.setAlgorithmHeaderValue(alg);
      jwe.setEncryptionMethodHeaderParameter(method);
      if (key.getKeyId() != null) {
        jwe.setKeyIdHeaderValue(key.getKeyId());
      }
      if (nested) {
        jwe.setContentTypeHeaderValue("JWT");
      }
      jwe.setKey(key.getPublicKey());
      jwe.setPayload(payload);
      return jwe.getCompactSerialization();
    } catch (JoseException ex) {
      throw new IllegalStateException("Unable to encrypt for " + client.getClientId(), ex);
    }
  }

  private Optional<PublicJsonWebKey> encryptionKey(ClientDetails client) {
    Optional<String> jwks =
        Optional.ofNullable(client.getJwksJson()).filter(j -> !j.isBlank()).or(() -> Optional
            .ofNullable(client.getJwksUri()).filter(u -> !u.isBlank()).flatMap(fetcher::fetch));
    if (jwks.isEmpty()) {
      return Optional.empty();
    }
    try {
      for (JsonWebKey jwk : new JsonWebKeySet(jwks.get()).getJsonWebKeys()) {
        boolean forEncryption = jwk.getUse() == null || "enc".equals(jwk.getUse());
        if (forEncryption && jwk instanceof RsaJsonWebKey rsa) {
          return Optional.of(rsa);
        }
      }
    } catch (JoseException ex) {
      return Optional.empty();
    }
    return Optional.empty();
  }
}
